html:
{%- set empresa = frappe.db.get_single_value("SIGOS Settings", "empresa_padrao") or frappe.db.get_single_value("Global Defaults", "default_company") -%}
{%- set logo = frappe.db.get_value("Company", empresa, "company_logo") if empresa else None -%}
{%- set codigo = (frappe.db.get_single_value("SIGOS Settings", "codigo_formulario_denuncia") or "").split("\n") | map("trim") | select | list -%}
{%- set local = frappe.db.get_single_value("SIGOS Settings", "local_documentos") or doc.delegacao or "" -%}
{%- set meses = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"] -%}
{%- set d = frappe.utils.getdate(doc.data) if doc.data else None -%}
{%- set sexo = frappe.db.get_value("Vigilante", doc.vigilante, "sexo") if doc.vigilante else None -%}
{%- macro data_local() -%}{{ local or "____________" }}, aos {{ "%02d" | format(d.day) if d else "____" }} de {{ meses[d.month - 1] if d else "______________" }} de {{ d.year if d else "20__" }}{%- endmacro -%}
{%- macro paragrafos(txt) -%}{% for par in (txt or "").split("\n\n") %}{% if par.strip() %}<p class="cx-p">{{ par.strip() | e | replace("\n", "<br>") }}</p>{% endif %}{% endfor %}{%- endmacro -%}
{%- macro codigos() -%}<table class="cx-cod"><tr><td>{{ (codigo[0] if codigo else "") | e }}</td><td class="r">{{ codigo[1:] | join(" ") | e }}</td></tr></table>{%- endmacro -%}
{%- macro propriedade() -%}{% if empresa %}<div class="cx-own">Este documento é propriedade da {{ empresa | upper }}. Não é permitida sua reprodução sem autorização.<br>Depois de impresso este documento é considerado cópia não controlada</div>{% endif %}{%- endmacro -%}
{%- macro estado() -%}{% if doc.docstatus == 0 %}<div class="cx-estado">RASCUNHO — não submetido</div>{% elif doc.docstatus == 2 %}<div class="cx-estado">CANCELADO</div>{% endif %}{%- endmacro -%}
<style>
	@page { size: A4 portrait; margin: 12mm 20mm 10mm 20mm; }
	.cx { font-family: "Times New Roman", Times, serif; color: #111; font-size: 16px; }
	.cx * { box-sizing: border-box; }
	.cx-pg { position: relative; min-height: 268mm; padding-bottom: 26mm; }
	.cx-logo { height: 84px; margin-bottom: 26px; position: relative; z-index: 1; }
	.cx-logo img { max-height: 84px; max-width: 190px; }
	.cx-wm { position: absolute; top: 62mm; left: 0; right: 0; text-align: center; opacity: .07; z-index: 0; }
	.cx-wm img { width: 160mm; }
	.cx-body { position: relative; z-index: 1; }
	.cx-p { line-height: 1.5; text-align: justify; margin: 0 0 12px; }
	.cx-estado { text-align: center; font-size: 11px; color: #888; letter-spacing: .08em; margin-bottom: 10px; }
	.cx-foot { position: absolute; left: 0; right: 0; bottom: 0; z-index: 1; }
	.cx-cod { width: 100%; font-size: 10.5px; font-style: italic; border-collapse: collapse; }
	.cx-cod td { padding: 0; } .cx-cod td.r { text-align: right; }
	.cx-own { text-align: center; font-size: 10px; font-style: italic; margin: 3px 30px; }
	.cx-ref { font-size: 8px; color: #999; text-align: right; }
	.cx-sig { border-top: 1px solid #111; }
	.dn-dest { line-height: 1.5; margin-bottom: 26px; }
	.dn-fecho { line-height: 1.5; margin-top: 18px; }
	.dn-data { margin: 26px 0 60px; }
	.dn-sig { width: 100%; border-collapse: collapse; }
	.dn-sig td { width: 50%; text-align: center; vertical-align: top; padding: 0 22px; }
</style>
<div class="cx"><div class="cx-pg">
	<div class="cx-logo">{% if logo %}<img src="{{ logo }}">{% endif %}</div>
	{%- if logo %}<div class="cx-wm"><img src="{{ logo }}"></div>{% endif %}
	<div class="cx-body">
		{{ estado() }}
		<div class="dn-dest">
			{{ "Exma. Senhora" if sexo == "Feminino" else "Exmo. Senhor" }}<br>
			{{ doc.nome_do_vigilante or doc.vigilante or "" }}<br><br>
			<b>Assunto: Denúncia do Período Probatório</b>
		</div>
		{{ paragrafos(doc.texto_carta) }}
		<div class="dn-fecho">Sem mais,<br>Subscrevemo-nos com estima e consideração!<br>Desde já, agradecemos pela cooperação,<br>Com os melhores cumprimentos</div>
		<div class="dn-data">{{ data_local() }}</div>
		<table class="dn-sig"><tr>
			<td><div class="cx-sig"></div>Director dos Recursos Humanos</td>
			<td><div class="cx-sig"></div>{{ "A Colaboradora" if sexo == "Feminino" else "O Colaborador" }}</td>
		</tr></table>
	</div>
	<div class="cx-foot">{{ codigos() }}{{ propriedade() }}<div class="cx-ref">{{ doc.name }}</div></div>
</div></div>
